import re,zlib
data=open('tool_appraisal.pdf','rb').read()
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    s=m.group(1)
    try: s=zlib.decompress(s)
    except Exception: pass
    txt=b' '.join(re.findall(rb'\((.*?)\)', s))
    if txt: print(txt.decode('latin-1'))
")

